>\n                </CButton>\n            </form>\n        </CCardBody>\n    </CCard>\n</template>\n<script>\n//\nimport { roles } from \"@/constants\";\n\nexport default {\n    name: \"PermissionForm\",\n    props: {\n        id: null\n    },\n    data() {\n        return {\n            formData: {},\n            errors: {},\n            fetchLoading: false,\n            updateLoading: false,\n            roles: roles\n        };\n    },\n    mounted() {\n        this.fetch();\n    },\n    methods: {\n        fetch() {\n            let self = this;\n            if (self.fetchLoading) {\n                return;\n            }\n            self.fetchLoading = true;\n            let data = {\n                id: self.$props.id\n            };\n            this.$store\n                .dispatch(\"user/permission/get\", data)\n                .then(response => {\n                    self.formData = JSON.parse(JSON.stringify(response.data));\n                    // console.log(response.data.data);\n                    self.fetchLoading = false;\n                })\n                .catch(error => {\n                    self.fetchLoading = false;\n                });\n        },\n        update() {\n            let self = this;\n            if (self.updateLoading) {\n                return;\n            }\n            self.updateLoading = true;\n            let data = {\n                ...self.formData,\n                id: self.$props.id\n            };\n            this.$store\n                .dispatch(\"user/permission/update\", data)\n                .then(response => {\n                    self.formData = JSON.parse(JSON.stringify(response.data));\n                    self.errors = {};\n                    self.updateLoading = false;\n                })\n                .catch(error => {\n                    self.errors = error.response.data?.data;\n                    self.updateLoading = false;\n                });\n        }\n    }\n};\n</script>\n\n<style scop